// ============================================================
// Neue Angebot-Kommentare filtern
// ============================================================
// Static Data: Letzten Check-Timestamp speichern
const staticData = $getWorkflowStaticData('global');
const letzterCheck = staticData.letzterCheck
  ? new Date(staticData.letzterCheck)
  : new Date(Date.now() - 10 * 60 * 1000); // Fallback: letzte 10 Min

// Aktuellen Timestamp für nächsten Lauf speichern
staticData.letzterCheck = new Date().toISOString();

// Trigger-Hashtags
const TRIGGER_TAGS = ['#angebot', '#quote'];

const ergebnisse = [];

for (const item of $input.all()) {
  const ticketId   = item.json.ticketId || item.json.id;
  const kundeId    = item.json.customerId || item.json.kunde_id || '';
  const kommentare = item.json.comments || item.json.history || [];

  for (const kommentar of kommentare) {
    // Zeitstempel-Prüfung
    const kommentarDatum = new Date(
      kommentar.createdAt || kommentar.created_at || kommentar.timestamp || 0
    );
    if (kommentarDatum <= letzterCheck) continue;

    // Trigger-Hashtag suchen (case-insensitive)
    const text = (kommentar.content || kommentar.text || '').toLowerCase();
    const gefundenerTag = TRIGGER_TAGS.find(tag => text.includes(tag));
    if (!gefundenerTag) continue;

    // Kommentartext nach dem Hashtag extrahieren
    const originalText = kommentar.content || kommentar.text || '';
    const tagIndex = originalText.toLowerCase().indexOf(gefundenerTag);
    const kommentarText = originalText.substring(tagIndex + gefundenerTag.length).trim();

    if (!kommentarText) continue;

    ergebnisse.push({
      json: {
        ticketId,
        kundeId,
        kommentarText,
        kommentarId:    kommentar.id,
        kommentarDatum: kommentarDatum.toISOString(),
        techniker:      kommentar.author || kommentar.techniker || 'Unbekannt',
        triggerTag:     gefundenerTag
      }
    });
  }
}

return ergebnisse.length > 0 ? ergebnisse : [{ json: { _keine_angebote: true } }];

// Geparste Positionen als natürlichsprachlichen Text serialisieren
// für das Embedding
const angebot = $input.first().json;
const kontextDaten = $('Neue Angebot-Kommentare filtern').item.json;

const gruppen = {};
for (const pos of (angebot.positionen || [])) {
  const kat = pos.kategorie || 'Sonstige';
  if (!gruppen[kat]) gruppen[kat] = [];
  gruppen[kat].push(`${pos.menge}x ${pos.bezeichnung} (${pos.geschaetzter_preis}€)`);
}

let text = `${angebot.angebot_typ} Angebot, ${(angebot.positionen || []).length} Positionen:\n`;
for (const [kat, positionen] of Object.entries(gruppen)) {
  text += `${kat}: ${positionen.join(', ')}\n`;
}
text += `Zusammenfassung: ${angebot.zusammenfassung}`;

return [{
  json: {
    ...angebot,
    serialisierterText: text,
    ticketId:   kontextDaten.ticketId,
    kundeId:    kontextDaten.kundeId,
    techniker:  kontextDaten.techniker,
    kommentarId: kontextDaten.kommentarId
  }
}];

