// ============================================================
// SAP B1 Quotation Payload aus geparsten Positionen bauen
// ============================================================
const angebot      = $('Angebot für Embedding serialisieren').item.json;
const ragErgebnis  = $('OpenAI: RAG Vollständigkeitsprüfung').item.json;
const s1Login      = $('S1: Login').item.json;

// Datum: heute im Format YYYY-MM-DD
const heute = new Date().toISOString().split('T')[0];

// Positionen aus geparsten Angebot in SAP-B1-Format überführen
const documentLines = (angebot.positionen || []).map((pos, index) => ({
  LineNum:          index,
  ItemDescription:  pos.bezeichnung,
  Quantity:         pos.menge,
  UnitPrice:        pos.geschaetzter_preis || 0,
  TaxCode:          process.env.S1_DEFAULT_TAX_CODE || 'T1',
  // ItemCode wird nur gesetzt wenn eine Artikelnummer vorhanden ist
  ...(pos.artikelNr ? { ItemCode: pos.artikelNr } : {})
}));

// Hinweis auf fehlende Positionen als Bemerkung anhängen
let comments = `Automatisch erstellt aus TANSS Ticket #${angebot.ticketId}\n`;
comments += `Erstellt von: ${angebot.techniker}\n`;

if (ragErgebnis.fehlende_positionen && ragErgebnis.fehlende_positionen.length > 0) {
  comments += `\nRAG-Hinweis (Vollständigkeit: ${Math.round((ragErgebnis.vollstaendigkeit_score || 0) * 100)}%):\n`;
  const kritische = ragErgebnis.fehlende_positionen.filter(p => p.prioritaet === 'KRITISCH');
  if (kritische.length > 0) {
    comments += `Ggf. fehlend: ${kritische.map(p => p.bezeichnung).join(', ')}`;
  }
}

const s1Payload = {
  CardCode:      angebot.kundeId || '',
  DocDate:       heute,
  DocDueDate:    heute,
  Comments:      comments,
  DocumentLines: documentLines,
  UserDefinedFields: {
    U_TANSS_TicketID: String(angebot.ticketId || '')
  }
};

return [{
  json: {
    s1Payload,
    s1Cookies: s1Login.cookies || '',
    angebot,
    ragErgebnis
  }
}];

// ============================================================
// TANSS-Rückmeldungs-Kommentar formatieren
// ============================================================
const s1Response  = $input.first().json;
const prevData    = $('S1 Quotation Payload bauen').item.json;
const ragErgebnis = prevData.ragErgebnis;
const angebot     = prevData.angebot;

// S1-Angebotsnummer und Link
const s1DocNum   = s1Response.DocNum   || s1Response.docNum   || 'unbekannt';
const s1DocEntry = s1Response.DocEntry || s1Response.docEntry || '';
const vollScore  = Math.round((ragErgebnis.vollstaendigkeit_score || 0) * 100);

// Fehlende Positionen nach Priorität gruppieren
const fehlende   = ragErgebnis.fehlende_positionen || [];
const kritische  = fehlende.filter(p => p.prioritaet === 'KRITISCH');
const empfohlen  = fehlende.filter(p => p.prioritaet === 'EMPFOHLEN');

let kommentar = `Angebot #${s1DocNum} wurde in Systemhaus.ONE erstellt.\n\n`;
kommentar += `RAG-Vollstaendigkeitspruefung (${vollScore}% vollstaendig):\n`;

if (fehlende.length === 0) {
  kommentar += `Alle typischen Positionen sind vorhanden.\n`;
} else {
  if (kritische.length > 0) {
    kommentar += `\nMoeglicherweise vergessen (KRITISCH):\n`;
    kritische.forEach(p => {
      kommentar += `- ${p.bezeichnung} (${p.typische_menge}x) – ${p.begruendung}\n`;
    });
  }
  if (empfohlen.length > 0) {
    kommentar += `\nEmpfohlen zu pruefen:\n`;
    empfohlen.forEach(p => {
      kommentar += `- ${p.bezeichnung}\n`;
    });
  }
  if (ragErgebnis.empfehlung) {
    kommentar += `\nEmpfehlung: ${ragErgebnis.empfehlung}\n`;
  }
}

kommentar += `\nS1-Angebot: ${process.env.S1_BASE_URL || ''}/b1s/v2/Quotations(${s1DocEntry})`;

return [{
  json: {
    ticketId:  angebot.ticketId,
    kommentar,
    s1DocNum,
    s1DocEntry
  }
}];
